project(hybrid_attention_mask_prep LANGUAGES CXX)

set(CMAKE_CXX_STANDARD 17)
set(CMAKE_CXX_STANDARD_REQUIRED ON)

find_package(CANN REQUIRED)
find_package(torch REQUIRED)

set(OP_NAME hybrid_attention_mask_prep)

# Find all kernel source files
file(GLOB_RECURSE KERNEL_SRCS ${CMAKE_CURRENT_SOURCE_DIR}/op_kernel/*.cpp)

# Build AscendC kernel object
ascendc_compile(
    TARGET ${OP_NAME}_kernel
    SOURCES ${KERNEL_SRCS}
)

# Build the Python extension .so
add_library(${OP_NAME}_ext SHARED
    ${CMAKE_CURRENT_SOURCE_DIR}/register.cpp
    ${CMAKE_CURRENT_SOURCE_DIR}/op_host/${OP_NAME}.cpp
)

target_include_directories(${OP_NAME}_ext PRIVATE
    ${CMAKE_CURRENT_SOURCE_DIR}
    ${CMAKE_CURRENT_SOURCE_DIR}/utils
    ${CANN_INCLUDE_DIRS}
    ${TORCH_INCLUDE_DIRS}
)

target_link_libraries(${OP_NAME}_ext PUBLIC
    ${TORCH_LIBRARIES}
    ${CANN_LIBRARIES}
)
