 */

#pragma once

#include "kernel_operator.h"
#include "kernel_common.h"
#include "hybrid_attention_mask_tiling.h"

class KernelHybridAttentionMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR full_out_gm,
        GM_ADDR swa_out_gm,
        GM_ADDR tiling_gm,
        AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tiling_gm);

        batch_size_ = tiling_.batch_size;
        num_heads_ = tiling_.num_heads;
        swa_num_heads_ = tiling_.swa_num_heads;
        target_length_ = tiling_.target_length;
        source_length_ = tiling_.source_length;
        past_kv_ = tiling_.past_kv;
        t_start_ = tiling_.t_start;
        t_end_ = tiling_.t_end;

        // Total elements per (batch, head) slice: target_length * source_length
        int64_t slice_elems = target_length_ * source_length_;

        full_out_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(full_out_gm),
            batch_size_ * num_heads_ * slice_elems);
        swa_out_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(swa_out_gm),
            batch_size_ * swa_num_heads_ * slice_elems);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            uint32_t row_bytes = AlignBytes(static_cast<uint32_t>(source_length_ * sizeof(uint8_t)));
            uint32_t col_idx_bytes = AlignBytes(static_cast<uint32_t>(source_length_ * sizeof(int32_t)));
            pipe_->InitBuffer(out_queue_, 1, row_bytes);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            // Create column index vector once
            // colIdx = [0, 1, 2, ..., source_length-1]
            AscendC::LocalTensor<int32_t> col_idx = out_queue_.AllocTensor<int32_t>();
            AscendC::CreateVecIndex(col_idx, 0);
            out_queue_.EnQue(col_idx);
            out_queue_.DeQue<int32_t>(col_idx);

            int64_t full_slice_elems = target_length_ * source_length_;
            int64_t swa_slice_elems = target_length_ * source_length_;

            // Process each T row assigned to this core
            for (int64_t t = t_start_; t < t_end_; ++t) {
                int32_t threshold = static_cast<int32_t>(t + past_kv_);

                // Compute full mask row: row_out = (col_idx > threshold)
                AscendC::LocalTensor<uint8_t> row_out = out_queue_.AllocTensor<uint8_t>();
                AscendC::CompareScalar(
                    row_out, col_idx, threshold,
                    AscendC::CMPMODE::GT,
                    static_cast<uint32_t>(source_length_));
                out_queue_.EnQue(row_out);
                out_queue_.DeQue<uint8_t>(row_out);

                // Copy full mask row to all (batch, head) positions
                uint32_t row_bytes = static_cast<uint32_t>(source_length_ * sizeof(uint8_t));
                AscendC::DataCopyExtParams copy_params{1, row_bytes, 0, 0, 0};
                for (int64_t b = 0; b < batch_size_; ++b) {
                    for (int64_t h = 0; h < num_heads_; ++h) {
                        int64_t offset = b * num_heads_ * full_slice_elems
                                       + h * full_slice_elems
                                       + t * source_length_;
                        AscendC::DataCopyPad(
                            full_out_[offset], row_out, copy_params);
                    }
                }

                out_queue_.FreeTensor(row_out);
            }

            // Free column index buffer
            out_queue_.FreeTensor(col_idx);
        }
    }

private:
    __aicore__ inline uint32_t AlignBytes(uint32_t bytes) const
    {
        return ((bytes + 31U) / 32U) * 32U;
    }

    HybridAttentionMaskTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};

    int64_t batch_size_{0};
    int64_t num_heads_{0};
    int64_t swa_num_heads_{0};
    int64_t target_length_{0};
    int64_t source_length_{0};
    int64_t past_kv_{0};
    int64_t t_start_{0};
    int64_t t_end_{0};

    AscendC::GlobalTensor<uint8_t> full_out_;
    AscendC::GlobalTensor<uint8_t> swa_out_;

    AscendC::TQue<AscendC::TPosition::VECIN, 0> in_queue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> out_queue_;
};
