#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_hybrid_attention_mask_prep.h"
#include "../op_kernel/hybrid_attention_mask_tiling.h"

namespace ascend_kernel {

std::tuple<at::Tensor, at::Tensor> hybrid_attention_mask_prep(
    int64_t batch_size_scalar,
    int64_t seq_length_scalar,
    int64_t past_key_values_length_scalar,
    int64_t num_attention_heads,
    int64_t swa_num_attention_heads,
    int64_t sliding_window)
{
    // ---- Compute shapes ----
    int64_t batch_size     = batch_size_scalar;
    int64_t target_length  = seq_length_scalar;
    int64_t source_length  = seq_length_scalar + past_key_values_length_scalar;
    int64_t past_kv        = past_key_values_length_scalar;
    int64_t num_heads      = num_attention_heads;
    int64_t swa_heads      = swa_num_attention_heads;

    // ---- Allocate output tensors on NPU ----
    // Full mask: kernel will fill with computed values
    auto full_out = at::empty(
        {batch_size, num_heads, target_length, source_length},
        at::TensorOptions().dtype(at::kByte).device(at::kPrivateUse1));

    // SWA mask: all zeros (per reference: zeros -> masked_fill(valid, False) -> all False)
    auto swa_out = at::zeros(
        {batch_size, swa_heads, target_length, source_length},
        at::TensorOptions().dtype(at::kByte).device(at::kPrivateUse1));

    // ---- Platform info ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t core_num = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ub_size;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ub_size);

    // ---- Tiling: split target_length across cores ----
    int64_t used_cores = core_num;
    if (used_cores > target_length) {
        used_cores = target_length;
    }
    if (used_cores < 1) {
        used_cores = 1;
    }

    int64_t base_rows_per_core = target_length / used_cores;
    int64_t remainder = target_length % used_cores;

    // ---- Build tiling data on CPU, then copy to NPU ----
    auto tiling_cpu = at::empty(
        {static_cast<int64_t>(sizeof(HybridAttentionMaskTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *tiling_ptr = reinterpret_cast<HybridAttentionMaskTiling *>(tiling_cpu.data_ptr());

    tiling_ptr->batch_size    = batch_size;
    tiling_ptr->num_heads     = num_heads;
    tiling_ptr->target_length = target_length;
    tiling_ptr->source_length = source_length;
    tiling_ptr->past_kv       = past_kv;
    tiling_ptr->t_start       = 0;  // placeholder, overwritten below

    // For non-uniform split: first 'remainder' cores get one extra row
    int64_t t_start = 0;
    for (int64_t c = 0; c < used_cores; ++c) {
        int64_t rows_this_core = base_rows_per_core + (c < remainder ? 1 : 0);
        int64_t t_end = t_start + rows_this_core;

        tiling_ptr->t_start = t_start;
        tiling_ptr->t_end   = t_end;

        auto tiling_npu = tiling_cpu.to(at::kPrivateUse1);
        uint32_t block_dim = 1;  // single core per launch since tiling is per-core

        // All parameters must be lvalues for EXEC_KERNEL_CMD
        EXEC_KERNEL_CMD(hybrid_attention_mask_prep, block_dim, full_out, tiling_npu);

        t_start = t_end;
    }

    return std::make_tuple(full_out, swa_out);
}

}  // namespace ascend_kernel
