        {static_cast<int64_t>(sizeof(HybridAttentionMaskTiling))},
        at::device(at::kCPU).dtype(at::kByte));
    auto *tiling_ptr = reinterpret_cast<HybridAttentionMaskTiling *>(tiling_cpu.data_ptr());

    tiling_ptr->batch_size    = batch_size;
    tiling_ptr->num_heads     = num_heads;
    tiling_ptr->target_length = target_length;
    tiling_ptr->source_length = source_length;
    tiling_ptr->past_kv       = past_kv;
    // t_start/t_end computed per-core in kernel based on core index

    auto tiling_npu = tiling_cpu.to(at::kPrivateUse1);
    uint32_t block_dim = static_cast<uint32_t>(core_num);

    // All params must be lvalues
    EXEC_KERNEL_CMD(hybrid_attention_mask_prep, block_dim, full_out, tiling_npu);

    return std::make_tuple(full_out, swa_out);
}

}  // namespace ascend_kernel
