                t_start = core_idx * (base_rows + 1);
                t_end   = t_start + base_rows + 1;
            } else {
                t_start = remainder * (base_rows + 1) + (core_idx - remainder) * base_rows;
                t_end   = t_start + base_rows;
            }

            if (t_start >= t_end) {
                return;  // nothing to do
            }

            int64_t slice_elems = target_length_ * source_length_;

            // Create column index vector using TBuf (avoid TQue for intermediate compute buffers)
            uint32_t col_idx_bytes = static_cast<uint32_t>(source_length_ * sizeof(int32_t));
            AscendC::TBuf<> col_idx_buf;
            AscendC::TBuf<> row_tmp_buf;
            pipe_->InitBuffer(col_idx_buf, AlignBytes(col_idx_bytes));
            pipe_->InitBuffer(row_tmp_buf, AlignBytes(static_cast<uint32_t>(source_length_ * sizeof(uint8_t))));

            AscendC::LocalTensor<int32_t> col_idx = col_idx_buf.Get<int32_t>(static_cast<uint32_t>(source_length_));
