43	    // ---- Platform info ----
44	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
45	    int64_t core_num_int64 = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
46	    int32_t core_num = static_cast<int32_t>(core_num_int64);
47	    if (core_num > static_cast<int32_t>(target_length)) {
48	        core_num = static_cast<int32_t>(target_length);
49	    }
50	    if (core_num < 1) {
51	        core_num = 1;
52	    }
53	
54	    // ---- Build tiling data ----
55	    auto tiling_cpu = at::empty(
56	        {static_cast<int64_t>(sizeof(HybridAttentionMaskTiling))},
57	        at::device(at::kCPU).dtype(at::kByte));
58	    auto *tiling_ptr = reinterpret_cast<HybridAttentionMaskTiling *>(tiling_cpu.data_ptr());
59	
60	    tiling_ptr->batch_size    = batch_size;
61	    tiling_ptr->num_heads     = num_heads;
62	    tiling_ptr->target_length = target_length;
63	    tiling_ptr->source_length = source_length;
64	    tiling_ptr->past_kv       = past_kv;
65	    // t_start/t_end computed per-core in kernel based on core index
66	
67	    auto tiling_npu = tiling_cpu.to(at::kPrivateUse1);
68	    uint32_t block_dim = static_cast<uint32_t>(core_num);
69	
70	    // All params must be lvalues
71	    EXEC_KERNEL_CMD(hybrid_attention_mask_prep, block_dim, full_out, tiling_npu);
72	
73	    return std::make_tuple(full_out, swa_out);
