class KernelHybridAttentionMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR full_out_gm,
        GM_ADDR tiling_gm,
        AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tiling_gm);
        batch_size_    = tiling_.batch_size;
        num_heads_     = tiling_.num_heads;
        target_length_ = tiling_.target_length;
        source_length_ = tiling_.source_length;
        past_kv_       = tiling_.past_kv;
        used_core_num_ = tiling_.used_core_num;

        int64_t total_elems = batch_size_ * num_heads_ * target_length_ * source_length_;
        full_out_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(full_out_gm), total_elems);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            uint32_t row_bytes = static_cast<uint32_t>(source_length_ * sizeof(uint8_t));
            uint32_t col_bytes = static_cast<uint32_t>(source_length_ * sizeof(int32_t));
            pipe_->InitBuffer(in_queue_, 1, col_bytes);
            // Use uint16_t for CompareScalar mask output (AscendC comparison produces 16-bit mask)
            pipe_->InitBuffer(mask_queue_, 1, static_cast<uint32_t>(
                ((source_length_ + 127) / 128) * 128 * sizeof(uint16_t) / 128));
            pipe_->InitBuffer(out_queue_, 1, row_bytes);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int64_t core_idx  = static_cast<int64_t>(AscendC::GetBlockIdx())
                              / static_cast<int64_t>(AscendC::GetSubBlockNum());
            int64_t num_cores = used_core_num_;
            int64_t base_rows = target_length_ / num_cores;
            int64_t remainder = target_length_ % num_cores;
            int64_t t_start, t_end;

            if (core_idx < remainder) {
                t_start = core_idx * (base_rows + 1);
                t_end   = t_start + base_rows + 1;
            } else {
                t_start = remainder * (base_rows + 1) + (core_idx - remainder) * base_rows;
                t_end   = t_start + base_rows;
            }
            if (t_start >= t_end) return;

            int64_t slice_elems = target_length_ * source_length_;
            uint32_t row_len = static_cast<uint32_t>(source_length_);
            uint32_t row_bytes = static_cast<uint32_t>(source_length_ * sizeof(uint8_t));

            // Create column index vector
            AscendC::LocalTensor<int32_t> col_idx;
            in_queue_.AllocTensor<int32_t>(col_idx);
            AscendC::CreateVecIndex(col_idx, static_cast<int32_t>(0),
                static_cast<uint32_t>(1), static_cast<uint32_t>(1),
                static_cast<uint32_t>(0), row_len);
            in_queue_.EnQue(col_idx);
            in_queue_.DeQue<int32_t>(col_idx);

            AscendC::DataCopyExtParams copy_params{1, row_bytes, 0, 0, 0};

            for (int64_t t = t_start; t < t_end; ++t) {
                int32_t threshold = static_cast<int32_t>(t + past_kv_);

                AscendC::LocalTensor<uint8_t> row_out;
                out_queue_.AllocTensor<uint8_t>(row_out);

                // Use SelMask flow: CompareScalar produces a selMask, then Select applies it
                // Step 1: fill with True (0xFF) - masked by default
                AscendC::Duplicate(row_out, static_cast<uint8_t>(0xFF), row_len);

                // Step 2: get comparison mask (col_idx <= threshold → False/visible)
                uint32_t mask_len = (row_len + 127) / 128 * 8; // ceil_div(row_len, 128) * 128/16
                AscendC::LocalTensor<uint16_t> sel_mask;
                mask_queue_.AllocTensor<uint16_t>(sel_mask);
                AscendC::CompareScalar(
                    sel_mask, col_idx, threshold,
                    AscendC::CMPMODE::LE, row_len);
                mask_queue_.EnQue(sel_mask);
                mask_queue_.DeQue<uint16_t>(sel_mask);

                // Step 3: Select → set False (0x00) where sel_mask indicates col_idx <= threshold
                AscendC::Select(row_out, sel_mask,
                    static_cast<uint8_t>(0x00), row_out,
                    AscendC::VSEL_TENSOR_SCALAR_MODE);

                out_queue_.EnQue(row_out);
                out_queue_.DeQue<uint8_t>(row_out);

                for (int64_t b = 0; b < batch_size_; ++b) {
                    for (int64_t h = 0; h < num_heads_; ++h) {
                        int64_t offset = b * num_heads_ * slice_elems
                                       + h * slice_elems
                                       + t * source_length_;
                        AscendC::DataCopyPad(full_out_[offset], row_out, copy_params);
                    }
                }
                out_queue_.FreeTensor(row_out);
                mask_queue_.FreeTensor(sel_mask);
            }
            in_queue_.FreeTensor(col_idx);
        }
    }

private:
    HybridAttentionMaskTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int64_t batch_size_{0}, num_heads_{0}, target_length_{0}, source_length_{0};
    int64_t past_kv_{0}, used_core_num_{0};
    AscendC::GlobalTensor<uint8_t> full_out_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0>  in_queue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> mask_queue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> out_queue_;
};
