{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 *
 * Computes full attention mask: True (masked) where col > row+past_kv.
 * Strategy: use int32_t arithmetic (Sub) then CompareScalar against 0.
 */

#pragma once

#include "kernel_operator.h"
#include "kernel_common.h"
#include "hybrid_attention_mask_tiling.h"

class KernelHybridAttentionMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR full_out_gm,
        GM_ADDR tiling_gm,
        AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tiling_gm);
        batch_size_    = tiling_.batch_size;
        num_heads_     = tiling_.num_heads;
        target_length_ = tiling_.target_length;
        source_length_ = tiling_.source_length;
        past_kv_       = tiling_.past_kv;
        used_core_num_ = tiling_.used_core_num;

        int64_t total_elems = batch_size_ * num_heads_ * target_length_ * source_length_;
        full_out_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(full_out_gm), total_elems);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            source_len_ = static_cast<uint32_t>(source_length_);
            // col_idx: int32_t vector
            pipe_->InitBuffer(col_queue_, 1,
                static_cast<uint32_t>(source_length_ * sizeof(int32_t)));
            // diff / thresh: int32_t work buffers
            uint32_t int32_bytes = static_cast<uint32_t>(source_length_ * sizeof(int32_t));
            pipe_->InitBuffer(work_queue_, 1, int32_bytes);
            // row_out: uint8_t mask
            pipe_->InitBuffer(out_queue_, 1,
                static_cast<uint32_t>(source_length_ * sizeof(uint8_t)) * 2);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int64_t core_idx  = static_cast<int64_t>(AscendC::GetBlockIdx())
                              / static_cast<int64_t>(AscendC::GetSubBlockNum());
            int64_t num_cores = used_core_num_;
            int64_t base_rows = target_length_ / num_cores;
            int64_t remainder = target_length_ % num_cores;
            int64_t t_start, t_end;

            if (core_idx < remainder) {
                t_start = core_idx * (base_rows + 1);
                t_end   = t_start + base_rows + 1;
            } else {
                t_start = remainder * (base_rows + 1) + (core_idx - remainder) * base_rows;
                t_end   = t_start + base_rows;
            }
            if (t_start >= t_end) return;

            int64_t slice_elems = target_length_ * source_length_;
            uint32_t row_bytes_out = static_cast<uint32_t>(source_length_ * sizeof(uint8_t));

            // Step 1: Create col_idx = [0, 1, 2, ..., S-1]
            AscendC::LocalTensor<int32_t> col_idx;
            col_queue_.AllocTensor<int32_t>(col_idx);
            AscendC::CreateVecIndex(col_idx, static_cast<int32_t>(0),
                static_cast<uint32_t>(1), static_cast<uint32_t>(1),
                static_cast<uint32_t>(0), source_len_);
            col_queue_.EnQue(col_idx);
            col_queue_.DeQue<int32_t>(col_idx);

            AscendC::DataCopyExtParams copy_params_out{1, row_bytes_out, 0, 0, 0};

            for (int64_t t = t_start; t < t_end; ++t) {
                int32_t threshold = static_cast<int32_t>(t + past_kv_);

                // Step 2: thresh_row = [threshold, threshold, ..., threshold]
                AscendC::LocalTensor<int32_t> thresh_row;
                work_queue_.AllocTensor<int32_t>(thresh_row);
                AscendC::Duplicate(thresh_row, threshold, source_len_);
                work_queue_.EnQue(thresh_row);
                work_queue_.DeQue<int32_t>(thresh_row);

                // Step 3: diff = col_idx - thresh_row  (int32_t)
                // diff[j] = j - threshold;  diff[j] > 0 means j > threshold
                AscendC::Sub(thresh_row, col_idx, thresh_row, source_len_);
                // Now thresh_row holds (j - threshold) values

                // Step 4: mask (uint8_t) where diff > 0  (i.e., j > threshold)
                AscendC::LocalTensor<uint8_t> row_out;
                out_queue_.AllocTensor<uint8_t>(row_out);
                AscendC::CompareScalar(
                    row_out, thresh_row, static_cast<int32_t>(0),
                    AscendC::CMPMODE::GT, source_len_);
                out_queue_.EnQue(row_out);
                out_queue_.DeQue<uint8_t>(row_out);

