{"content": "/*
 * Copyright (c) 2026 Huawei Technologies Co., Ltd.
 *
 * Uses Compares (replacement for CompareScalar in CANN 9.0) with
 * isSetMask=true to produce per-element mask values (0xFF/0x00 per byte).
 */

#pragma once

#include "kernel_operator.h"
#include "kernel_common.h"
#include "hybrid_attention_mask_tiling.h"

class KernelHybridAttentionMaskPrep {
public:
    __aicore__ inline void Init(
        GM_ADDR full_out_gm,
        GM_ADDR tiling_gm,
        AscendC::TPipe *pipe)
    {
        CopyTiling(&tiling_, tiling_gm);
        batch_size_    = tiling_.batch_size;
        num_heads_     = tiling_.num_heads;
        target_length_ = tiling_.target_length;
        source_length_ = tiling_.source_length;
        past_kv_       = tiling_.past_kv;
        used_core_num_ = tiling_.used_core_num;

        int64_t total_elems = batch_size_ * num_heads_ * target_length_ * source_length_;
        full_out_.SetGlobalBuffer(
            reinterpret_cast<__gm__ uint8_t *>(full_out_gm), total_elems);

        if ASCEND_IS_AIV {
            pipe_ = pipe;
            source_len_ = static_cast<uint32_t>(source_length_);
            uint32_t int32_bytes = static_cast<uint32_t>(source_length_ * sizeof(int32_t));
            uint32_t uint8_bytes = static_cast<uint32_t>(source_length_ * sizeof(uint8_t));
            pipe_->InitBuffer(col_queue_, 1, int32_bytes);
            pipe_->InitBuffer(work_queue_, 1, int32_bytes);
            pipe_->InitBuffer(out_queue_, 1, uint8_bytes * 2);
        }
    }

    __aicore__ inline void Process()
    {
        if ASCEND_IS_AIV {
            int64_t core_idx  = static_cast<int64_t>(AscendC::GetBlockIdx())
                              / static_cast<int64_t>(AscendC::GetSubBlockNum());
            int64_t num_cores = used_core_num_;
            int64_t base_rows = target_length_ / num_cores;
            int64_t remainder = target_length_ % num_cores;
            int64_t t_start, t_end;

            if (core_idx < remainder) {
                t_start = core_idx * (base_rows + 1);
                t_end   = t_start + base_rows + 1;
            } else {
                t_start = remainder * (base_rows + 1) + (core_idx - remainder) * base_rows;
                t_end   = t_start + base_rows;
            }
            if (t_start >= t_end) return;

            int64_t slice_elems = target_length_ * source_length_;
            uint32_t row_bytes_out = static_cast<uint32_t>(source_length_ * sizeof(uint8_t));

            // Create col_idx = [0, 1, 2, ..., S-1] as int32_t
            AscendC::LocalTensor<int32_t> col_idx;
            col_queue_.AllocTensor<int32_t>(col_idx);
            AscendC::CreateVecIndex(col_idx, static_cast<int32_t>(0),
                static_cast<uint32_t>(1), static_cast<uint32_t>(1),
                static_cast<uint32_t>(0), source_len_);
            col_queue_.EnQue(col_idx);
            col_queue_.DeQue<int32_t>(col_idx);

            AscendC::DataCopyExtParams copy_params_out{1, row_bytes_out, 0, 0, 0};

            for (int64_t t = t_start; t < t_end; ++t) {
                int32_t threshold = static_cast<int32_t>(t + past_kv_);

                // Work buffer: compute diff = col_idx - threshold (int32_t)
                AscendC::LocalTensor<int32_t> diff;
                work_queue_.AllocTensor<int32_t>(diff);

                // Fill with threshold values, then sub
                AscendC::Duplicate(diff, threshold, source_len_);
                work_queue_.EnQue(diff);
                work_queue_.DeQue<int32_t>(diff);

                // diff = col_idx - threshold;  diff[j] = j - threshold
                AscendC::Sub(diff, col_idx, diff, source_len_);

                // Produce uint8_t mask: 0xFF where diff > 0, 0x00 where diff <= 0
                AscendC::LocalTensor<uint8_t> row_out;
                out_queue_.AllocTensor<uint8_t>(row_out);

                // Mask: all 64 bits set (compare all elements)
                uint64_t mask_arr[2] = {0xFFFFFFFFFFFFFFFFULL, 0x0ULL};
                AscendC::UnaryRepeatParams repeat_params;
                repeat_params.dstBlkStride = 1;
                repeat_params.srcBlkStride = 1;
                repeat_params.dstRepStride = 0;
                repeat_params.srcRepStride = 0;

                AscendC::Compares<int32_t, uint8_t, true>(
                    row_out, diff, static_cast<int32_t>(0),
                    AscendC::CMPMODE::GT, mask_arr,
                    static_cast<uint8_t>(1), repeat_params);

                out_queue_.EnQue(row_out);
                out_queue_.DeQue<uint8_t>(row_out);

                work_queue_.FreeTensor(diff);

                for (int64_t b = 0; b < batch_size_; ++b) {
                    for (int64_t h = 0; h < num_heads_; ++h) {
                        int64_t offset = b * num_heads_ * slice_elems
                                       + h * slice_elems
                                       + t * source_length_;
                        AscendC::DataCopyPad(
                            full_out_[offset], row_out, copy_params_out);
                    }
                }
                out_queue_.FreeTensor(row_out);
            }
            col_queue_.FreeTensor(col_idx);
        }
    }

private:
    HybridAttentionMaskTiling tiling_{};
    AscendC::TPipe *pipe_{nullptr};
    int64_t batch_size_{0}, num_heads_{0}, target_length_{0}, source_length_{0};
    int64_t past_kv_{0}, used_core_num_{0};
    uint32_t source_len_{0};
    AscendC::GlobalTensor<uint8_t> full_out_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0>  col_queue_;
    AscendC::TQue<AscendC::TPosition::VECIN, 0>  work_queue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, 0> out_queue_;
};
